    "testCode": "```typescript\n// Bug Reproduction Test — TokenManager.refresh should not throw when auth state is missing or method is invoked without binding\n\n/**\n * These tests are written to reproduce the reported bug:\n *   TypeError: Cannot read properties of undefined\n * at:\n *   TokenManager.refresh (src/auth/token.ts:45)\n *\n * Test strategy:\n * - Integration-style class test against the real TokenManager implementation\n * - Reproduces the main failure mode by clearing auth state before refresh\n * - Covers an edge case where refresh is called before auth state exists\n * - Covers a regression check for detached/lost `this` binding\n *\n * Notes:\n * - The import path assumes the app exports TokenManager from src/auth/token\n * - If constructor dependencies differ, update the factory helper below\n * - Assertions are intentionally written to FAIL with the current bug and PASS once fixed\n */\n\nimport { TokenManager } from '../../src/auth/token';\n\ndescribe('TokenManager.refresh bug reproduction', () => {\n  let originalLocalStorage: Storage | undefined;\n  let originalSessionStorage: Storage | undefined;\n\n  /**\n   * Minimal in-memory Storage mock so tests can simulate browser auth state.\n   */\n  const createStorageMock = (): Storage => {\n    let store: Record<string, string> = {};\n\n    return {\n      get length() {\n        return Object.keys(store).length;\n      },\n      clear: jest.fn(() => {\n        store = {};\n      }),\n      getItem: jest.fn((key: string) => (key in store ? store[key] : null)),\n      key: jest.fn((index: number) => Object.keys(store)[index] ?? null),\n      removeItem: jest.fn((key: string) => {\n        delete store[key];\n      }),\n      setItem: jest.fn((key: string, value: string) => {\n        store[key] = String(value);\n      }),\n    };\n  };\n\n  /**\n   * Factory helper for creating TokenManager in a tolerant way because\n   * constructor details were not provided in the bug report.\n   *\n   * If your implementation requires constructor args, replace this with\n   * the appropriate real dependencies/mocks.\n   */\n  const createTokenManager = (): TokenManager => {\n    try {\n      return new TokenManager();\n    } catch (err) {\n      throw new Error(\n        `Unable to construct TokenManager with no args. Update createTokenManager() in this test to match the real constructor.\\nOriginal error: ${String(\n          err\n        )}`\n      );\n    }\n  };\n\n  beforeEach(() => {\n    jest.restoreAllMocks();\n\n    // Preserve existing globals so test environment is restored cleanly.\n    originalLocalStorage = global.localStorage;\n    originalSessionStorage = global.sessionStorage;\n\n    Object.defineProperty(global, 'localStorage', {\n      value: createStorageMock(),\n      configurable: true,\n      writable: true,\n    });\n\n    Object.defineProperty(global, 'sessionStorage', {\n      value: createStorageMock(),\n      configurable: true,\n      writable: true,\n    });\n  });\n\n  afterEach(() => {\n    // Restore original globals after each test.\n    Object.defineProperty(global, 'localStorage', {\n      value: originalLocalStorage,\n      configurable: true,\n      writable: true,\n    });\n\n    Object.defineProperty(global, 'sessionStorage', {\n      value: originalSessionStorage,\n      configurable: true,\n      writable: true,\n    });\n  });\n\n  it('should handle missing auth state gracefully when refresh is triggered after login state is cleared', async () => {\n    const tokenManager = createTokenManager();\n\n    // Simulate previously authenticated state existing in storage.\n    // Key names are intentionally broad based on the bug report.\n    localStorage.setItem(\n      'auth',\n      JSON.stringify({\n        accessToken: 'old-access-token',\n        refreshToken: 'old-refresh-token',\n        expiresAt: Date.now() + 60_000,\n      })\n    );\n    localStorage.setItem('refreshToken', 'old-refresh-token');\n    sessionStorage.setItem('token', 'old-access-token');\n\n    // Reproduce the bug condition: auth state is cleared without page reload.\n    localStorage.removeItem('auth');\n    localStorage.removeItem('refreshToken');\n    sessionStorage.removeItem('token');\n\n    // Main bug assertion:\n    // With the bug, this typically throws TypeError due to reading a property of undefined.\n    // When fixed, it should either no-op or reject in a controlled, non-TypeError way.\n    await expect(tokenManager.refresh()).resolves.not.toThrow();\n  });\n\n  it('should not throw a TypeError when refresh is called before auth-store hydration or with empty storage', async () => {\n    const tokenManager = createTokenManager();\n\n    // Edge case: app startup or hydration gap where no auth state exists yet.\n    localStorage.clear();\n    sessionStorage.clear();\n\n    // This should not crash on undefined property access.\n    // A correct implementation should safely return, reject gracefully, or indicate no refresh is possible.\n    await expect(tokenManager.refresh()).resolves.not.toThrow();\n  });\n\n  it('should preserve method safety when refresh is invoked as a detached callback instead of crashing from lost this binding', async () => {\n    const tokenManager = createTokenManager();\n\n    // Regression check for the \"lost binding\" hypothesis from the bug report.\n    // If refresh relies on `this` and is not bound/defensive, this can reproduce\n    // the same undefined-property failure path.\n    const detachedRefresh = tokenManager.refresh;\n\n    // Calling as a detached function should not produce the raw TypeError.\n    // After a fix, the implementation should either bind correctly or fail gracefully.\n    await expect(detachedRefresh()).resolves.not.toThrow();\n  });\n});\n```\n\n### Notes to make this executable in your repo\nYou may need one small adjustment depending on the real implementation:\n\n1. **Import path**\n   - If your tests live elsewhere, update:\n   ```ts\n   import { TokenManager } from '../../src/auth/token';\n   ```\n\n2. **Constructor shape**\n   - If `TokenManager` requires dependencies, update `createTokenManager()` to pass real mocks.\n\n3. **Async vs sync refresh**\n   - These tests assume `refresh()` returns a Promise, which is typical for token refresh logic.\n   - If it is synchronous, replace:\n   ```ts\n   await expect(tokenManager.refresh()).resolves.not.toThrow();\n   ```\n   with:\n   ```ts\n   expect(() => tokenManager.refresh()).not.toThrow();\n   ```\n\nIf you want, I can also generate a version tailored to your exact `src/auth/token.ts` implementation if you paste that file.",
