    "title": "Admin logout every 15min despite 24h timeout setting",
    "inputType": "raw_text",
    "rawInput": "Admin users are being logged out every 15 minutes even though the session timeout is set to 24 hours in the application settings.",
    "githubUrl": null,
    "codeContext": null,
