    "extractedEntities": "{\"component\":\"AuthenticationService\",\"triggerAction\":\"Concurrent JWT refresh on token expiry\",\"expectedBehavior\":\"Single token refresh, all requests succeed with new token\",\"actualBehavior\":\"Multiple refresh calls issued simultaneously, tokens overwrite each other causing 401 on stale tokens\",\"environment\":{\"runtime\":\"Node.js 20\",\"version\":\"auth-service v3.2.1\"},\"errorMessages\":[\"401 Unauthorized: token_revoked\",\"JWT signature verification failed: key rotation conflict\"],\"frequency\":\"intermittent\",\"additionalContext\":\"Observed under load when >5 concurrent requests hit an expired token simultaneously. Implementing a refresh lock (mutex) resolves the issue.\"}",
    "hypotheses": "[{\"id\":\"h1\",\"title\":\"Missing refresh token mutex\",\"mechanism\":\"Without a distributed lock, concurrent token refresh requests each spawn independent refresh flows, creating a race condition where the last writer wins and invalidates all prior refresh attempts.\",\"likelihood\":\"high\",\"confirmingEvidence\":[\"Multiple 401s logged within same 50ms window\",\"Auth service log shows concurrent refresh_token calls\"],\"refutingEvidence\":[],\"status\":\"retained\",\"statusReason\":\"Direct match with missing mutex in AuthService.refreshToken()\"}]",
    "reproductionSteps": "{\"prerequisites\":[\"Active user session with JWT access token\",\"Token within 60s of expiry\"],\"steps\":[{\"number\":1,\"action\":\"Issue 5+ concurrent API requests from same session\",\"expectedOutcome\":\"All requests trigger simultaneous token refresh\"},{\"number\":2,\"action\":\"Observe auth service logs for concurrent refresh_token calls\"},{\"number\":3,\"action\":\"Check responses — later responses return 401 with token_revoked\"}],\"expectedResult\":\"Single refresh completes, all requests succeed\",\"actualResult\":\"Multiple refreshes race; subsequent calls fail with stale tokens\",\"environmentConfig\":[\"Active user session with JWT access token\",\"Token within 60s of expiry\"],\"validationNotes\":[\"Verify with Redis lock implementation as fix\"],\"confidenceRating\":8}",
    "testCode": "// Bug Reproduction Test — JWT refresh race condition\nimport { createAuthClient } from '../src/auth';\n\ndescribe('JWT refresh concurrency', () => {\n  it('should not issue multiple concurrent refresh calls', async () => {\n    const client = createAuthClient({ tokenTtl: 1 });\n    await client.login('user@example.com', 'password');\n    // Expire the token\n    await new Promise(r => setTimeout(r, 1100));\n    // Fire 5 concurrent requests\n    const results = await Promise.allSettled(\n      Array.from({ length: 5 }, () => client.get('/api/profile'))\n    );\n    const failures = results.filter(r => r.status === 'rejected');\n    expect(failures).toHaveLength(0);\n  });\n});",
