    "extractedEntities": "{\"component\":\"SessionManagementService\",\"triggerAction\":\"Password change via account settings\",\"expectedBehavior\":\"All existing sessions invalidated after password rotation\",\"actualBehavior\":\"Sessions on other devices remain authenticated with old credential hash\",\"environment\":{\"runtime\":\"Node.js 18\",\"version\":\"user-service v2.8.0\"},\"errorMessages\":[\"Session validation bypass: credential hash mismatch ignored\",\"Security policy violation: active session post-password-change\"],\"frequency\":\"always\",\"additionalContext\":\"Password change should revoke all active refresh tokens and session cookies. Requires iterating session store and invalidating all tokens associated with userId.\"}",
