    "reproductionSteps": "{\"prerequisites\":[\"User logged in on two devices (Device A and Device B)\"],\"steps\":[{\"number\":1,\"action\":\"On Device A, navigate to Account > Security > Change Password\"},{\"number\":2,\"action\":\"Submit new password\"},{\"number\":3,\"action\":\"On Device B, attempt any authenticated API call\"}],\"expectedResult\":\"Device B receives 401, user must re-authenticate\",\"actualResult\":\"Device B session remains active with no interruption\",\"environmentConfig\":[\"User logged in on two devices (Device A and Device B)\"],\"validationNotes\":[\"Verify session store has active tokens for userId after password change\"],\"confidenceRating\":8}",
    "testCode": "// Bug Reproduction Test — session persistence after password change\ndescribe('PasswordChangeService', () => {\n  it('invalidates all sessions after password change', async () => {\n    const userId = await createUser('test@example.com', 'old-password');\n    const session = await issueSession(userId);\n    await changePassword(userId, 'old-password', 'new-password');\n    const result = await validateSession(session.token);\n    expect(result.valid).toBe(false);\n  });\n});",
