    "rawInput": "After a user completes account recovery via email link, the session ID from before the recovery is reused. An attacker who observes the pre-recovery session ID can inject it into their browser and bypass 2FA entirely since the recovered session is marked as fully authenticated.",
    "githubUrl": null,
    "codeContext": null,
    "tags": "authentication,2fa,security,session,account-recovery,fixation,seed-data",
    "status": "completed",
    "severity": "critical",
    "severityReason": "Session fixation attack allows 2FA bypass — attacker can hijack recovered sessions.",
    "confidenceScore": 0.93,
    "confidenceBreakdown": "{\"score\":93,\"rubric\":{\"stack_trace\":0,\"code_context\":15,\"reproduction_steps\":25,\"error_message\":20,\"environment\":10,\"frequency\":5,\"similar_bug\":20},\"missing\":[\"stack_trace\"],\"evidence\":[\"Penetration test confirmed session fixation vector\",\"Recovery flow does not regenerate session ID\"],\"assumptions\":[]}",
    "extractedEntities": "{\"component\":\"AccountRecoveryService\",\"triggerAction\":\"Email-based account recovery with 2FA enabled\",\"expectedBehavior\":\"New session issued post-recovery, old session invalidated\",\"actualBehavior\":\"Session ID preserved across recovery flow, bypassing 2FA requirement\",\"environment\":{\"runtime\":\"Node.js 20\",\"version\":\"account-service v4.1.0\"},\"errorMessages\":[\"Session fixation: pre-recovery session_id accepted post-authentication\",\"2FA enforcement skipped: session.mfa_verified=true inherited from recovery\"],\"frequency\":\"rare\",\"additionalContext\":\"Must call session.regenerate() after successful recovery to issue a new session ID. All previous session IDs must be invalidated.\"}",
    "hypotheses": "[{\"id\":\"h1\",\"title\":\"session.regenerate() not called post-recovery\",\"mechanism\":\"Express session stores the session_id in a cookie. If session.regenerate() is not called after authentication level changes (recovery, 2FA), the same session_id is reused, enabling session fixation.\",\"likelihood\":\"high\",\"confirmingEvidence\":[\"Session ID before and after recovery confirmed identical in test environment\",\"mfa_verified flag set on session without re-challenge after recovery\"],\"refutingEvidence\":[],\"status\":\"retained\",\"statusReason\":\"Security audit finding — missing session.regenerate() call\"}]",
    "reproductionSteps": "{\"prerequisites\":[\"Account with 2FA enabled\",\"Network interception capability (DevTools)\"],\"steps\":[{\"number\":1,\"action\":\"Start account recovery flow, note session cookie value\"},{\"number\":2,\"action\":\"Complete recovery via email link\"},{\"number\":3,\"action\":\"Inject pre-recovery session ID into new browser\"},{\"number\":4,\"action\":\"Attempt access to 2FA-protected endpoint\"}],\"expectedResult\":\"2FA challenge presented\",\"actualResult\":\"Access granted with pre-recovery session ID\",\"environmentConfig\":[\"Account with 2FA enabled\",\"Network interception capability (DevTools)\"],\"validationNotes\":[],\"confidenceRating\":8}",
    "testCode": "// Bug Reproduction Test — session fixation post-recovery\ndescribe('AccountRecoveryService', () => {\n  it('regenerates session ID after account recovery', async () => {\n    const agent = request.agent(app);\n    await agent.post('/auth/recovery/start').send({ email: 'user@test.com' });\n    const before = agent.jar.getCookies('http://localhost')[0]?.value;\n    await agent.post('/auth/recovery/complete').send({ token: 'valid-token' });\n    const after = agent.jar.getCookies('http://localhost')[0]?.value;\n    expect(before).not.toEqual(after);\n  });\n});",
