    "inputType": "raw_text",
    "rawInput": "Database deadlocks observed during peak checkout periods. Two concurrent order submissions each acquire a row lock on their respective inventory items and then attempt to acquire the lock held by the other transaction. PostgreSQL deadlock detector terminates one transaction, which surfaces as a 500 error to the user.",
    "githubUrl": null,
    "codeContext": null,
    "tags": "deadlock,concurrency,database,transaction,inventory,postgresql,seed-data",
    "status": "completed",
    "severity": "high",
    "severityReason": "Deadlocks during checkout cause order failures — direct revenue loss and poor user experience.",
    "confidenceScore": 0.87,
    "confidenceBreakdown": "{\"score\":87,\"rubric\":{\"stack_trace\":25,\"code_context\":15,\"reproduction_steps\":25,\"error_message\":20,\"environment\":10,\"frequency\":5,\"similar_bug\":0},\"missing\":[],\"evidence\":[\"Stack trace shows deadlock_detected\",\"PostgreSQL pg_locks confirms lock ordering conflict\"],\"assumptions\":[]}",
    "extractedEntities": "{\"component\":\"OrderService\",\"triggerAction\":\"Concurrent order submissions with overlapping inventory items\",\"expectedBehavior\":\"Orders complete without deadlock\",\"actualBehavior\":\"PostgreSQL deadlock terminates one order transaction\",\"environment\":{\"runtime\":\"PostgreSQL 15\",\"version\":\"order-service v5.1.0\"},\"errorMessages\":[\"ERROR: deadlock detected DETAIL: Process 1234 waits for ShareLock on transaction 5678\",\"HINT: See server log for query details\",\"deadlock_detected: transaction rolled back\"],\"frequency\":\"intermittent\",\"additionalContext\":\"Fix by acquiring inventory locks in consistent order (ORDER BY product_id) to prevent circular lock dependency.\"}",
    "hypotheses": "[{\"id\":\"h1\",\"title\":\"Inconsistent lock acquisition order across transactions\",\"mechanism\":\"Transaction A locks inventory[product_1] then inventory[product_2]. Simultaneously Transaction B locks inventory[product_2] then inventory[product_1]. Both wait for the other's lock — classic deadlock from inconsistent lock ordering.\",\"likelihood\":\"high\",\"confirmingEvidence\":[\"Deadlock graph in pg_locks confirms circular wait\",\"Both transactions modify same product inventory rows in different order\"],\"refutingEvidence\":[],\"status\":\"retained\",\"statusReason\":\"Deadlock graph confirms lock order inversion\"}]",
    "reproductionSteps": "{\"prerequisites\":[\"Products with shared inventory items in cart\",\"PostgreSQL with row-level locking\"],\"steps\":[{\"number\":1,\"action\":\"Submit two concurrent orders both containing product_id=1 and product_id=2\"},{\"number\":2,\"action\":\"Observe PostgreSQL logs for deadlock_detected error\"},{\"number\":3,\"action\":\"Verify one order returns 500 while the other completes\"}],\"expectedResult\":\"Both orders complete successfully\",\"actualResult\":\"One order returns 500: deadlock detected\",\"environmentConfig\":[\"Products with shared inventory items in cart\",\"PostgreSQL with row-level locking\"],\"validationNotes\":[],\"confidenceRating\":8}",
    "testCode": "// Bug Reproduction Test — checkout deadlock\ndescribe('OrderService', () => {\n  it('processes concurrent orders without deadlock', async () => {\n    const [order1, order2] = await Promise.allSettled([\n      submitOrder({ items: [{ productId: 1 }, { productId: 2 }] }),\n      submitOrder({ items: [{ productId: 2 }, { productId: 1 }] }),\n    ]);\n    expect(order1.status).toBe('fulfilled');\n    expect(order2.status).toBe('fulfilled');\n  });\n});",
