    "inputType": "raw_text",
    "rawInput": "Real-time notification feed shows messages out of order when multiple events are broadcast simultaneously. The WebSocket server emits events as they complete async database queries, not in the order they were received. Two notifications fired within the same millisecond can arrive at clients in reversed order.",
    "githubUrl": null,
    "codeContext": null,
    "tags": "websocket,concurrency,async,ordering,broadcast,race-condition,seed-data",
    "status": "completed",
    "severity": "medium",
    "severityReason": "Out-of-order notifications confuse users and can cause incorrect UI state — lower severity but affects perceived reliability.",
    "confidenceScore": 0.72,
    "confidenceBreakdown": "{\"score\":72,\"rubric\":{\"stack_trace\":0,\"code_context\":15,\"reproduction_steps\":25,\"error_message\":20,\"environment\":5,\"frequency\":5,\"similar_bug\":0},\"missing\":[\"stack_trace\",\"environment\"],\"evidence\":[\"Message timestamps confirm out-of-order delivery\",\"Async DB query completion races observed in logs\"],\"assumptions\":[\"Network latency may mask reordering\"]}",
    "extractedEntities": "{\"component\":\"NotificationBroadcastService\",\"triggerAction\":\"Concurrent notification broadcast via WebSocket\",\"expectedBehavior\":\"Messages delivered to clients in order of event creation\",\"actualBehavior\":\"Messages arrive in order of async query completion, not event order\",\"environment\":{\"runtime\":\"Node.js 20\",\"version\":\"notification-service v1.6.0\"},\"errorMessages\":[\"Message reordering detected: notification.sequence out of order\",\"WebSocket broadcast race: event_b delivered before event_a despite later timestamp\"],\"frequency\":\"intermittent\",\"additionalContext\":\"Assign a monotonic sequence number at event creation time and sort client-side, or use a message queue with ordering guarantees (e.g. Redis Streams).\"}",
    "hypotheses": "[{\"id\":\"h1\",\"title\":\"Async DB enrichment races before broadcast\",\"mechanism\":\"Each notification triggers an async DB query to enrich payload. Events fired in rapid succession complete their enrichment queries at different speeds, causing out-of-order emission to the WebSocket clients.\",\"likelihood\":\"high\",\"confirmingEvidence\":[\"Slower DB queries complete after faster ones, reversing order\",\"Notifications without async enrichment deliver in correct order\"],\"refutingEvidence\":[],\"status\":\"retained\",\"statusReason\":\"Async enrichment latency confirmed as reordering cause\"}]",
    "reproductionSteps": "{\"prerequisites\":[\"WebSocket client connected\",\"Two notification triggers 5ms apart\"],\"steps\":[{\"number\":1,\"action\":\"Trigger notification A with slow DB enrichment (50ms)\"},{\"number\":2,\"action\":\"Trigger notification B with fast DB enrichment (5ms)\"},{\"number\":3,\"action\":\"Observe client WebSocket message order\"}],\"expectedResult\":\"Client receives A then B\",\"actualResult\":\"Client receives B then A\",\"environmentConfig\":[\"WebSocket client connected\",\"Two notification triggers 5ms apart\"],\"validationNotes\":[],\"confidenceRating\":8}",
    "testCode": "// Bug Reproduction Test — WebSocket message ordering\ndescribe('NotificationBroadcastService', () => {\n  it('delivers concurrent notifications in creation order', async () => {\n    const received: string[] = [];\n    ws.on('message', (data) => received.push(JSON.parse(data).id));\n    await Promise.all([broadcastNotification('a', 50), broadcastNotification('b', 5)]);\n    await new Promise(r => setTimeout(r, 100));\n    expect(received).toEqual(['a', 'b']);\n  });\n});",
