    "testCode": "// Bug Reproduction Test — Profile page crashes with TypeError when a user logs in via SSO for the first time without email address\nimport React from 'react';\nimport { render, fireEvent, waitFor } from '@testing-library/react';\nimport { ProfilePage } from './ProfilePage';\nimport { SSOProvider } from './SSOProvider';\n\ndescribe('Profile Page Rendering', () => {\n  beforeEach(() => {\n    // Mock SSO provider to not return email address in identity payload\n    jest.spyOn(SSOProvider, 'getIdentityPayload').mockImplementation(() => ({ email: null }));\n  });\n\n  afterEach(() => {\n    jest.clearAllMocks();\n  });\n\n  it('should render profile page successfully with default or placeholder values for missing fields', () => {\n    // Render profile page\n    const { getByText } = render(<ProfilePage />);\n\n    // Wait for profile page to load\n    waitFor(() => {\n      expect(getByText('Profile Page')).toBeInTheDocument();\n    });\n\n    // Verify email address is not accessed directly without null checking\n    expect(() => getByText('Email: ')).toThrowError(TypeError);\n  });\n\n  it('should handle edge case where SSO provider returns empty string for email address', () => {\n    // Mock SSO provider to return empty string for email address\n    jest.spyOn(SSOProvider, 'getIdentityPayload').mockImplementation(() => ({ email: '' }));\n\n    // Render profile page\n    const { getByText } = render(<ProfilePage />);\n\n    // Wait for profile page to load\n    waitFor(() => {\n      expect(getByText('Profile Page')).toBeInTheDocument();\n    });\n\n    // Verify email address is rendered with default or placeholder value\n    expect(getByText('Email:')).toBeInTheDocument();\n  });\n\n  it('should render profile page successfully after fixing bug', () => {\n    // Mock SSO provider to return email address in identity payload\n    jest.spyOn(SSOProvider, 'getIdentityPayload').mockImplementation(() => ({ email: 'user@example.com' }));\n\n    // Render profile page\n    const { getByText } = render(<ProfilePage />);\n\n    // Wait for profile page to load\n    waitFor(() => {\n      expect(getByText('Profile Page')).toBeInTheDocument();\n    });\n\n    // Verify email address is rendered correctly\n    expect(getByText('Email: user@example.com')).toBeInTheDocument();\n  });\n});",
