    "testCode": "// Bug Reproduction Test — Payment webhook processor crashes with NullPointerException when Stripe sends a payment_intent.succeeded event for an intent that has no associated order in our database\nimport Stripe from 'stripe';\nimport { PaymentWebhookProcessor } from './payment-webhook-processor';\n\nconst stripe = new Stripe('api_key', { apiVersion: '2022-11-15' });\nconst paymentWebhookProcessor = new PaymentWebhookProcessor();\n\ndescribe('PaymentWebhookProcessor', () => {\n  it('should handle payment_intent.succeeded event without crashing when no associated order is found', () => {\n    // Mock Stripe payment intent\n    const paymentIntent = stripe.paymentIntents.create({\n      amount: 100,\n      currency: 'usd',\n      payment_method_types: ['card']\n    });\n\n    // Simulate payment_intent.succeeded event\n    const event = {\n      id: 'evt_123',\n      type: 'payment_intent.succeeded',\n      data: {\n        object: paymentIntent\n      }\n    };\n\n    // Mock database query to return no results for the payment intent\n    jest.spyOn(paymentWebhookProcessor, 'getOrderForPaymentIntent').mockResolvedValue(null);\n\n    // Process the event\n    const result = paymentWebhookProcessor.processEvent(event);\n\n    // Assertions\n    expect(result).not.toThrow();\n    expect(paymentWebhookProcessor.logger.warn).toHaveBeenCalledTimes(1);\n    expect(paymentWebhookProcessor.logger.error).not.toHaveBeenCalled();\n  });\n\n  it('should log a warning when no associated order is found', () => {\n    // Mock Stripe payment intent\n    const paymentIntent = stripe.paymentIntents.create({\n      amount: 100,\n      currency: 'usd',\n      payment_method_types: ['card']\n    });\n\n    // Simulate payment_intent.succeeded event\n    const event = {\n      id: 'evt_123',\n      type: 'payment_intent.succeeded',\n      data: {\n        object: paymentIntent\n      }\n    };\n\n    // Mock database query to return no results for the payment intent\n    jest.spyOn(paymentWebhookProcessor, 'getOrderForPaymentIntent').mockResolvedValue(null);\n\n    // Process the event\n    paymentWebhookProcessor.processEvent(event);\n\n    // Assertions\n    expect(paymentWebhookProcessor.logger.warn).toHaveBeenCalledTimes(1);\n    expect(paymentWebhookProcessor.logger.warn).toHaveBeenCalledWith('No associated order found for payment intent %s', paymentIntent.id);\n  });\n\n  it('should handle payment_intent.succeeded event with an associated order', () => {\n    // Mock Stripe payment intent\n    const paymentIntent = stripe.paymentIntents.create({\n      amount: 100,\n      currency: 'usd',\n      payment_method_types: ['card']\n    });\n\n    // Simulate payment_intent.succeeded event\n    const event = {\n      id: 'evt_123',\n      type: 'payment_intent.succeeded',\n      data: {\n        object: paymentIntent\n      }\n    };\n\n    // Mock database query to return an order for the payment intent\n    const order = { id: 'ord_123', paymentIntentId: paymentIntent.id };\n    jest.spyOn(paymentWebhookProcessor, 'getOrderForPaymentIntent').mockResolvedValue(order);\n\n    // Process the event\n    const result = paymentWebhookProcessor.processEvent(event);\n\n    // Assertions\n    expect(result).not.toThrow();\n    expect(paymentWebhookProcessor.logger.warn).not.toHaveBeenCalled();\n    expect(paymentWebhookProcessor.logger.error).not.toHaveBeenCalled();\n  });\n});",
