    "id": 96,
    "title": "Stripe payment intent creation times out under high load",
    "inputType": "raw_text",
    "rawInput": "Payment processing endpoint times out when Stripe's API takes more than 10 seconds to respond during high-load periods. The HTTP client has a default 10s timeout that is too aggressive for payment operations. Stripe recommends idempotency keys and retry logic for timeout scenarios, neither of which are implemented.",
    "githubUrl": null,
    "codeContext": null,
    "tags": "timeout,api,payment,stripe,network,retry,connection,seed-data",
    "status": "completed",
    "severity": "critical",
    "severityReason": "Payment failures during high load cause direct revenue loss and duplicate charge risk without idempotency.",
    "confidenceScore": 0.9,
    "confidenceBreakdown": "{\"score\":90,\"rubric\":{\"stack_trace\":25,\"code_context\":15,\"reproduction_steps\":25,\"error_message\":20,\"environment\":10,\"frequency\":5,\"similar_bug\":0},\"missing\":[],\"evidence\":[\"Timeout error captured with Stripe request ID\",\"Load test confirms timeout at >500 rps\"],\"assumptions\":[]}",
    "extractedEntities": "{\"component\":\"PaymentIntentService\",\"triggerAction\":\"Create payment intent during checkout under load\",\"expectedBehavior\":\"Payment intent created, client secret returned within 5s\",\"actualBehavior\":\"ConnectTimeout: Stripe API request exceeded 10s timeout limit\",\"environment\":{\"runtime\":\"Node.js 20\",\"version\":\"payment-service v3.2.0\"},\"errorMessages\":[\"ConnectTimeout: request to https://api.stripe.com/v1/payment_intents timed out\",\"StripeConnectionError: Network communication with Stripe failed\",\"Request ID: req_missing — timeout before response received\"],\"frequency\":\"intermittent\",\"additionalContext\":\"Increase timeout to 30s for payment operations. Add idempotency key to prevent duplicate charges on retry. Implement circuit breaker to fail fast when Stripe is degraded.\"}",
    "hypotheses": "[{\"id\":\"h1\",\"title\":\"HTTP client timeout too aggressive for payment API\",\"mechanism\":\"The default 10s timeout is shorter than Stripe's P99 response time under load. Stripe recommends 30s timeout for payment operations. Without idempotency keys, retries risk duplicate charges.\",\"likelihood\":\"high\",\"confirmingEvidence\":[\"Stripe status page shows elevated P99 during incident\",\"10s timeout reproducible under load test\"],\"refutingEvidence\":[],\"status\":\"retained\",\"statusReason\":\"Timeout threshold too low for payment API SLA\"}]",
    "reproductionSteps": "{\"prerequisites\":[\"Load testing tool (k6/Artillery)\",\"Stripe test mode credentials\"],\"steps\":[{\"number\":1,\"action\":\"Run load test with 500 concurrent checkout requests\"},{\"number\":2,\"action\":\"Observe payment intent creation response times\"},{\"number\":3,\"action\":\"Check for timeout errors in application logs\"}],\"expectedResult\":\"All payment intents created within 5s\",\"actualResult\":\"Timeout errors appear at >100 concurrent requests\",\"environmentConfig\":[\"Load testing tool (k6/Artillery)\",\"Stripe test mode credentials\"],\"validationNotes\":[],\"confidenceRating\":8}",
    "testCode": "// Bug Reproduction Test — Stripe timeout handling\ndescribe('PaymentIntentService', () => {\n  it('uses idempotency key on retry after timeout', async () => {\n    const stripeClient = mockStripeWithDelay(12000);\n    const service = new PaymentIntentService({ client: stripeClient, timeout: 30000 });\n    const result = await service.createWithRetry({ amount: 1000, currency: 'usd' });\n    expect(stripeClient.paymentIntents.create).toHaveBeenCalledWith(\n      expect.anything(),\n      expect.objectContaining({ idempotencyKey: expect.any(String) })\n    );\n  });\n});",
    "testSyntaxStatus": "verified",
