    "severityReason": "Export feature completely broken for cross-region S3 buckets — Lambda timeouts waste compute and block export queue.",
    "confidenceScore": 0.78,
    "confidenceBreakdown": "{\"score\":78,\"rubric\":{\"stack_trace\":0,\"code_context\":15,\"reproduction_steps\":25,\"error_message\":20,\"environment\":10,\"frequency\":5,\"similar_bug\":0},\"missing\":[\"stack_trace\",\"similar_bug\"],\"evidence\":[\"Lambda timeout logs confirm hanging AWS SDK call\",\"Cross-region S3 access confirmed via bucket configuration\"],\"assumptions\":[]}",
    "extractedEntities": "{\"component\":\"FileExportService\",\"triggerAction\":\"Generate presigned multipart upload URL for large export\",\"expectedBehavior\":\"Presigned URL returned within 2s\",\"actualBehavior\":\"AWS SDK createMultipartUpload hangs, Lambda times out after 900s\",\"environment\":{\"runtime\":\"AWS Lambda Node.js 20\",\"version\":\"export-service v1.3.0\"},\"errorMessages\":[\"Task timed out after 900.00 seconds (Lambda max)\",\"AWS SDK: no response received for s3.createMultipartUpload request\",\"RequestTimeout: socket hang up after 600000ms\"],\"frequency\":\"always\",\"additionalContext\":\"Set requestTimeout and connectionTimeout on S3 client. Use same-region S3 bucket or configure VPC endpoint. Add CloudWatch alarm for Lambda timeout metric.\"}",
    "hypotheses": "[{\"id\":\"h1\",\"title\":\"Missing SDK timeout on cross-region S3 request\",\"mechanism\":\"The S3 SDK client has no requestTimeout configured. Cross-region requests with VPC routing issues can hang indefinitely, blocking the Lambda until its 15-minute execution limit.\",\"likelihood\":\"high\",\"confirmingEvidence\":[\"Lambda CloudWatch logs show timeout at exactly 900s (configured limit)\",\"Same call with same-region bucket completes in 200ms\"],\"refutingEvidence\":[],\"status\":\"retained\",\"statusReason\":\"Cross-region hang with no timeout confirmed\"}]",
    "reproductionSteps": "{\"prerequisites\":[\"Lambda in us-east-1\",\"S3 bucket in eu-west-1 with no cross-region replication\"],\"steps\":[{\"number\":1,\"action\":\"Trigger export for file >1GB\"},{\"number\":2,\"action\":\"Observe Lambda execution logs\"},{\"number\":3,\"action\":\"Wait for Lambda timeout (15 minutes)\"}],\"expectedResult\":\"Presigned URL returned within 2s\",\"actualResult\":\"Lambda hangs for 900s then times out\",\"environmentConfig\":[\"Lambda in us-east-1\",\"S3 bucket in eu-west-1 with no cross-region replication\"],\"validationNotes\":[],\"confidenceRating\":8}",
    "testCode": "// Bug Reproduction Test — S3 SDK timeout configuration\ndescribe('FileExportService', () => {\n  it('uses requestTimeout on S3 client', () => {\n    const service = new FileExportService();\n    const s3Config = service.getS3ClientConfig();\n    expect(s3Config.requestHandler.requestTimeout).toBeLessThanOrEqual(30000);\n  });\n});",
