    "id": 100,
    "title": "Infinite render loop in product filter useEffect with object dependency",
    "inputType": "raw_text",
    "rawInput": "Product listing page freezes browser tab with 100% CPU usage when the filter panel is opened. A useEffect hook depends on a filterOptions object that is recreated on every render. Since the object reference changes each render cycle, the effect fires again, which updates state, which triggers a re-render, which creates a new object reference — infinite loop.",
    "githubUrl": null,
    "codeContext": null,
    "tags": "react,rendering,useeffect,infinite-loop,state,component,performance,seed-data",
    "status": "completed",
    "severity": "high",
    "severityReason": "Browser tab freeze on filter interaction makes the product listing page completely unusable — core e-commerce functionality broken.",
    "confidenceScore": 0.91,
    "confidenceBreakdown": "{\"score\":91,\"rubric\":{\"stack_trace\":25,\"code_context\":15,\"reproduction_steps\":25,\"error_message\":20,\"environment\":10,\"frequency\":5,\"similar_bug\":0},\"missing\":[],\"evidence\":[\"React DevTools confirms infinite render loop\",\"useEffect dependency array identified as root cause\"],\"assumptions\":[]}",
    "extractedEntities": "{\"component\":\"ProductFilterComponent\",\"triggerAction\":\"Open filter panel on product listing page\",\"expectedBehavior\":\"Filter panel opens, products filtered without performance issues\",\"actualBehavior\":\"Browser tab freezes: infinite render loop caused by useEffect with object reference dependency\",\"environment\":{\"browser\":\"Chrome 120\",\"runtime\":\"React 18\",\"version\":\"product-listing v4.2.0\"},\"errorMessages\":[\"Warning: Maximum update depth exceeded\",\"useEffect triggered 10000+ times in 500ms\",\"React error: too many re-renders, likely caused by infinite update loop\"],\"frequency\":\"always\",\"additionalContext\":\"Memoize filterOptions with useMemo or move it outside the component. Use JSON.stringify comparison or deep-equal custom hook for object dependencies.\"}",
    "hypotheses": "[{\"id\":\"h1\",\"title\":\"Object reference in useEffect dependency causes infinite loop\",\"mechanism\":\"filterOptions is created inline: const filterOptions = { categories, priceRange }. Each render creates a new object reference. useEffect([filterOptions, fetchProducts]) detects a new reference every render, calls fetchProducts, which updates state, triggering another render.\",\"likelihood\":\"high\",\"confirmingEvidence\":[\"React DevTools shows render count exceeding 10000 within 1 second\",\"Wrapping filterOptions in useMemo stops the loop\"],\"refutingEvidence\":[],\"status\":\"retained\",\"statusReason\":\"Object reference instability in useEffect deps confirmed\"}]",
    "reproductionSteps": "{\"prerequisites\":[\"React app with product listing page\",\"DevTools open to Components tab\"],\"steps\":[{\"number\":1,\"action\":\"Navigate to product listing page\"},{\"number\":2,\"action\":\"Click any filter checkbox\"},{\"number\":3,\"action\":\"Observe browser CPU usage and React render count\"}],\"expectedResult\":\"Products filter, render count stable\",\"actualResult\":\"Browser tab freezes, render count increases indefinitely\",\"environmentConfig\":[\"React app with product listing page\",\"DevTools open to Components tab\"],\"validationNotes\":[],\"confidenceRating\":8}",
    "testCode": "// Bug Reproduction Test — useEffect infinite loop\nimport { renderHook } from '@testing-library/react';\nimport { act } from 'react';\n\ndescribe('ProductFilterComponent', () => {\n  it('does not cause excessive renders on filter change', () => {\n    let renderCount = 0;\n    const { rerender } = render(<ProductFilter onRender={() => renderCount++} />);\n    act(() => { rerender(<ProductFilter categories={['electronics']} onRender={() => renderCount++} />); });\n    expect(renderCount).toBeLessThan(5);\n  });\n});",
    "testSyntaxStatus": "verified",
