    "title": "Virtualized list scroll position resets to top on data refresh",
    "inputType": "raw_text",
    "rawInput": "The transaction history list jumps to the top when background data polling refreshes the list. The virtualized list component receives a new array reference on every poll response (even when data is identical), which triggers a full re-render and resets the scroll position. Users lose their place in long transaction histories.",
    "githubUrl": null,
    "codeContext": null,
    "tags": "react,rendering,virtualized,scroll,state,component,list,seed-data",
    "status": "completed",
    "severity": "medium",
    "severityReason": "Users lose reading position on data refresh — frustrating UX for customers reviewing transaction histories.",
    "confidenceScore": 0.71,
    "confidenceBreakdown": "{\"score\":71,\"rubric\":{\"stack_trace\":0,\"code_context\":15,\"reproduction_steps\":25,\"error_message\":20,\"environment\":5,\"frequency\":5,\"similar_bug\":0},\"missing\":[\"stack_trace\",\"environment\",\"similar_bug\"],\"evidence\":[\"New array reference on identical data confirmed\",\"Scroll reset triggered by prop change in virtualized component\"],\"assumptions\":[]}",
    "extractedEntities": "{\"component\":\"TransactionListComponent\",\"triggerAction\":\"Background polling refreshes transaction list data\",\"expectedBehavior\":\"Scroll position preserved during background refresh with identical data\",\"actualBehavior\":\"Virtualized list remounts and scroll resets to position 0 on every poll\",\"environment\":{\"browser\":\"Chrome 120\",\"runtime\":\"React 18\",\"version\":\"transaction-history v3.0.0\"},\"errorMessages\":[\"VirtualizedList: key prop change detected, remounting list\",\"scroll_position_reset: new items prop reference causes scroll to 0\",\"Polling creates new array: items !== prevItems despite identical content\"],\"frequency\":\"always\",\"additionalContext\":\"Memoize the items array to preserve reference stability when data is unchanged. Use deep comparison in useMemo or normalize API responses before passing to list component.\"}",
    "hypotheses": "[{\"id\":\"h1\",\"title\":\"New array reference on every poll response\",\"mechanism\":\"Each successful poll creates a new array: setItems(response.data). Even if response.data has identical content, it is a new reference. The virtualized list component uses referential equality for change detection, remounting when items prop reference changes.\",\"likelihood\":\"high\",\"confirmingEvidence\":[\"Replacing setItems(response.data) with setItems(prev => isEqual(prev, response.data) ? prev : response.data) prevents reset\",\"React DevTools confirms VirtualizedList remounts on every poll\"],\"refutingEvidence\":[],\"status\":\"retained\",\"statusReason\":\"Reference instability on poll response confirmed as root cause\"}]",
    "reproductionSteps": "{\"prerequisites\":[\"Transaction list with >50 items\",\"Background polling enabled (30s interval)\"],\"steps\":[{\"number\":1,\"action\":\"Scroll to item #40 in the transaction list\"},{\"number\":2,\"action\":\"Wait 30 seconds for background poll to complete\"},{\"number\":3,\"action\":\"Observe scroll position\"}],\"expectedResult\":\"Scroll position maintained at item #40\",\"actualResult\":\"List jumps to top (item #1)\",\"environmentConfig\":[\"Transaction list with >50 items\",\"Background polling enabled (30s interval)\"],\"validationNotes\":[],\"confidenceRating\":8}",
    "testCode": "// Bug Reproduction Test — scroll position on data refresh\ndescribe('TransactionListComponent', () => {\n  it('preserves scroll position on background refresh with identical data', async () => {\n    const { getScrollTop, triggerRefresh } = renderTransactionList(mockTransactions);\n    simulateScroll(500);\n    await triggerRefresh(mockTransactions);\n    expect(getScrollTop()).toBe(500);\n  });\n});",
