    "extractedEntities": "{\"component\":\"ModalComponent\",\"triggerAction\":\"Close modal dialog in Safari browser\",\"expectedBehavior\":\"Modal closes, overlay removed, page interactive\",\"actualBehavior\":\"Overlay DOM element persists, pointer events blocked on entire page\",\"environment\":{\"os\":\"macOS 14\",\"browser\":\"Safari 17\",\"runtime\":\"React 18\"},\"errorMessages\":[\"animationend event not dispatched in Safari 17 with CSS animation\",\"Modal.onExited callback never called: animation lifecycle incomplete\",\"pointer-events blocked: overlay z-index covers page content\"],\"frequency\":\"always\",\"additionalContext\":\"Add setTimeout fallback for animationend in Safari: if (!onExited called within 400ms, force-remove overlay). Or replace CSS animation with JS animation via requestAnimationFrame.\"}",
    "hypotheses": "[{\"id\":\"h1\",\"title\":\"Safari does not fire animationend for certain CSS animations\",\"mechanism\":\"The modal uses CSS animation for fade-out. Safari 17 has a known bug where animationend is not dispatched when the animation uses certain timing functions with transform. React Transition Group waits for this event to unmount the DOM node.\",\"likelihood\":\"high\",\"confirmingEvidence\":[\"Overlay persists 100% of time in Safari 17\",\"animationend listener confirmed never called via DevTools breakpoint in Safari\"],\"refutingEvidence\":[\"Behavior is Safari-specific, Chrome and Firefox unaffected\"],\"status\":\"retained\",\"statusReason\":\"Safari animationend bug confirmed as root cause\"}]",
    "reproductionSteps": "{\"prerequisites\":[\"Safari 17 on macOS\",\"Page with modal dialog trigger\"],\"steps\":[{\"number\":1,\"action\":\"Open any modal dialog\"},{\"number\":2,\"action\":\"Click the close button\"},{\"number\":3,\"action\":\"Wait for fade-out animation to complete visually\"},{\"number\":4,\"action\":\"Attempt to click any element on the underlying page\"}],\"expectedResult\":\"Modal closes, page is interactive\",\"actualResult\":\"Clicks not registered, page unresponsive — overlay blocks interaction\",\"environmentConfig\":[\"Safari 17 on macOS\",\"Page with modal dialog trigger\"],\"validationNotes\":[],\"confidenceRating\":8}",
