    "title": "N+1 query on user dashboard causes 30-second page load",
    "inputType": "raw_text",
    "rawInput": "User dashboard takes 25-30 seconds to load for accounts with many projects. Investigation reveals an N+1 query pattern: the dashboard loads all projects in one query (N=150), then executes a separate query for each project's latest activity (N queries), totaling 151 database round trips. Each query has ~200ms latency, resulting in 30+ seconds total.",
    "githubUrl": null,
    "codeContext": null,
    "tags": "database,performance,query,slow,postgresql,nplusone,optimization,seed-data",
    "status": "completed",
    "severity": "high",
    "severityReason": "30-second dashboard load is effectively unusable — high-value users with many projects have the worst experience.",
    "confidenceScore": 0.88,
    "confidenceBreakdown": "{\"score\":88,\"rubric\":{\"stack_trace\":0,\"code_context\":15,\"reproduction_steps\":25,\"error_message\":20,\"environment\":10,\"frequency\":5,\"similar_bug\":10},\"missing\":[\"stack_trace\"],\"evidence\":[\"Database query log shows 151 sequential queries\",\"N+1 pattern identified in ORM code review\"],\"assumptions\":[]}",
    "extractedEntities": "{\"component\":\"DashboardDataService\",\"triggerAction\":\"Load user dashboard with projects and latest activity\",\"expectedBehavior\":\"Dashboard loads in under 1s with single joined query\",\"actualBehavior\":\"151 sequential database queries execute, page load takes 30s\",\"environment\":{\"runtime\":\"Node.js 20, PostgreSQL 15\",\"version\":\"dashboard-service v3.1.0\"},\"errorMessages\":[\"slow query: dashboard loaded in 28432ms\",\"N+1 query detected: 150 separate queries for project activity\",\"pg_stat_statements shows getProjectActivity called 150 times per dashboard load\"],\"frequency\":\"always\",\"additionalContext\":\"Replace individual getProjectActivity calls with a single JOIN or CTE. Use ORM eager loading: Project.findAll({ include: [LatestActivity] }).\"}",
    "hypotheses": "[{\"id\":\"h1\",\"title\":\"N+1 query in dashboard project activity loading\",\"mechanism\":\"DashboardService loads projects array then iterates: for (const project of projects) { await getProjectActivity(project.id) }. Each getProjectActivity is a separate SQL query. With 150 projects, this is 150 sequential DB round trips.\",\"likelihood\":\"high\",\"confirmingEvidence\":[\"Query log shows 150 identical SELECT queries with different project_id values\",\"Replacing loop with JOIN reduces load to 1 query and 200ms\"],\"refutingEvidence\":[],\"status\":\"retained\",\"statusReason\":\"N+1 pattern confirmed in service code and query logs\"}]",
    "reproductionSteps": "{\"prerequisites\":[\"User account with >100 projects\",\"Database query logging enabled\"],\"steps\":[{\"number\":1,\"action\":\"Log in as user with 150 projects\"},{\"number\":2,\"action\":\"Navigate to dashboard\"},{\"number\":3,\"action\":\"Count database queries in logs during load\"}],\"expectedResult\":\"Dashboard loads in <1s with single query\",\"actualResult\":\"150+ sequential queries, 30s load time\",\"environmentConfig\":[\"User account with >100 projects\",\"Database query logging enabled\"],\"validationNotes\":[],\"confidenceRating\":8}",
    "testCode": "// Bug Reproduction Test — N+1 query on dashboard\ndescribe('DashboardDataService', () => {\n  it('loads dashboard with single query for all project activities', async () => {\n    const queryCount = { value: 0 };\n    db.on('query', () => queryCount.value++);\n    await loadDashboard(userId);\n    db.off('query');\n    expect(queryCount.value).toBeLessThan(5);\n  });\n});",
